import{_ as o,o as a,c as t,a4 as i}from"./chunks/framework.DzALyu-k.js";const r="/copilot-studio-masterclass/assets/passo4-01.DA7eI3gj.png",n="/copilot-studio-masterclass/assets/passo4-02.DP59DtRT.png",l="/copilot-studio-masterclass/assets/passo4-03.CI0xc7OX.png",v=JSON.parse('{"title":"Lab 00 - Setup dati: il PMO Demand Hub","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/standard-harness/00-setup-dati/index.md","filePath":"advanced/standard-harness/00-setup-dati/README.md"}'),s={name:"advanced/standard-harness/00-setup-dati/index.md"};function d(c,e,p,m,g,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="lab-00-setup-dati-il-pmo-demand-hub" tabindex="-1">Lab 00 - Setup dati: il PMO Demand Hub <a class="header-anchor" href="#lab-00-setup-dati-il-pmo-demand-hub" aria-label="Permalink to &quot;Lab 00 - Setup dati: il PMO Demand Hub&quot;">​</a></h1><p><span class="icon"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M224,128a96,96,0,1,1-96-96A96,96,0,0,1,224,128Z" opacity="0.2"></path><path d="M232,136.66A104.12,104.12,0,1,1,119.34,24,8,8,0,0,1,120.66,40,88.12,88.12,0,1,0,216,135.34,8,8,0,0,1,232,136.66ZM120,72v56a8,8,0,0,0,8,8h56a8,8,0,0,0,0-16H136V72a8,8,0,0,0-16,0Zm40-24a12,12,0,1,0-12-12A12,12,0,0,0,160,48Zm36,24a12,12,0,1,0-12-12A12,12,0,0,0,196,72Zm24,36a12,12,0,1,0-12-12A12,12,0,0,0,220,108Z"></path></svg></span> <strong>Tempo stimato:</strong> ~45 minuti · <span class="icon f-standard"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M232,120v72a8,8,0,0,1-8,8H32a8,8,0,0,1-8-8V120Z" opacity="0.2"></path><path d="M224,64H176V56a24,24,0,0,0-24-24H104A24,24,0,0,0,80,56v8H32A16,16,0,0,0,16,80V192a16,16,0,0,0,16,16H224a16,16,0,0,0,16-16V80A16,16,0,0,0,224,64ZM96,56a8,8,0,0,1,8-8h48a8,8,0,0,1,8,8v8H96ZM32,80H224v32H192v-8a8,8,0,0,0-16,0v8H80v-8a8,8,0,0,0-16,0v8H32ZM224,192H32V128H64v8a8,8,0,0,0,16,0v-8h96v8a8,8,0,0,0,16,0v-8h32v64Z"></path></svg></span> <strong>Harness:</strong> standard</p><h2 id="scenario" tabindex="-1">Scenario <a class="header-anchor" href="#scenario" aria-label="Permalink to &quot;Scenario&quot;">​</a></h2><p>Zava S.p.A. è una società tecnologica italiana con 420 dipendenti, sede a Milano e uffici a Torino, Bologna e Roma. Ogni anno le funzioni aziendali (Acquisti, Vendite, Risorse Umane, Servizio Clienti, IT Operations, Sicurezza) propongono nuovi progetti IT. Le proposte vengono finanziate attraverso cinque <strong>programmi di investimento</strong>, ciascuno con un budget e con criteri di valutazione propri.</p><p>Il processo è gestito dall&#39;<strong>Ufficio Demand e PMO IT</strong> e oggi funziona così:</p><ul><li>le proposte arrivano in una casella email condivisa, in formati diversi, spesso senza tutte le informazioni richieste;</li><li>un analista apre ogni documento, lo registra in un foglio Excel e lo assegna a un programma;</li><li>la valutazione con i criteri pesati viene fatta a mano, con interpretazioni diverse da analista ad analista;</li><li>per ogni proposta valutata si prepara un dossier per il Comitato (circa due ore di lavoro);</li><li>la sessione di revisione con lo sponsor e l&#39;architetto di riferimento si organizza con molti scambi di email.</li></ul><p>I problemi sono noti: tempi di presa in carico lunghi, valutazioni poco confrontabili, dossier con strutture diverse, poco tempo per l&#39;analisi vera e propria. Nei laboratori di questo percorso il PMO affida la parte ripetitiva a un sistema di agenti, guidato dall&#39;<strong>Agente Demand IT</strong>, e lascia le decisioni alle persone coinvolte nel processo:</p><table tabindex="0"><thead><tr><th>Attore</th><th>Ruolo nel processo</th><th>Interagisce con</th></tr></thead><tbody><tr><td>Proponente</td><td>Responsabile di funzione che presenta il business case</td><td>Agente Demand IT (chat) oppure email</td></tr><tr><td>Analista PMO</td><td>Verifica, conferma il programma, conferma la registrazione della valutazione</td><td>Agente Demand IT, PMO Demand Hub, Teams</td></tr><tr><td>Sponsor interno</td><td>Dirigente che risponde della proposta</td><td>Sessione di revisione</td></tr><tr><td>Architetto di riferimento</td><td>Valuta gli aspetti tecnici per il programma</td><td>Agente Comitato, sessione di revisione</td></tr><tr><td>Comitato</td><td>Decide</td><td>Dossier di revisione</td></tr></tbody></table><p>Il primo passo non riguarda ancora gli agenti. Oggi i dati del processo sono sparsi tra la casella email e un foglio Excel: serve prima un archivio comune e strutturato, che persone e agenti possano leggere e scrivere.</p><p>Questo archivio è il <strong>PMO Demand Hub</strong>, e il corso lo fornisce già pronto, come Agent Academy fa per l&#39;Hiring Agent: una soluzione Dataverse con le cinque tabelle del processo (Programmi, Criteri di valutazione, Proponenti, Proposte, Valutazioni) e l&#39;app model-driven <strong>PMO Demand Hub</strong> per consultarle, modificarle e importare dati. In questo laboratorio si legge prima con attenzione che cosa contiene la soluzione: nomi logici, codici automatici, scelte e relazioni sono quelli che gli agenti useranno in tutti i laboratori successivi. Poi la soluzione viene importata, vengono caricati i dati di partenza (cinque programmi di investimento con i loro criteri pesati) e viene preparata in SharePoint la cartella con i documenti di conoscenza del PMO. In particolare verranno svolte le seguenti attività:</p><ul><li>Capire tabelle, colonne, scelte e relazioni del modello dati.</li><li>Conoscere l&#39;app <strong>PMO Demand Hub</strong>: home page, import CSV e Proposal Board.</li><li>Importare la soluzione <strong>PMO Demand IT</strong>.</li><li>Caricare i cinque programmi e i 25 criteri di valutazione.</li><li>Preparare la cartella SharePoint della conoscenza PMO.</li></ul><p>Ogni record del PMO Demand Hub ha un codice leggibile: Proposta <code>PP-####</code>, Valutazione <code>AS-####</code>, Proponente <code>RQ-####</code>, Programma <code>PG-###</code>. Gli agenti leggono questi codici dai risultati degli strumenti e non li inventano mai. I codici del proprio ambiente saranno diversi da quelli degli esempi: nelle prove si controlla la forma, non il valore.</p><details class="details custom-block"><summary><span class="icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M208,104a79.86,79.86,0,0,1-30.59,62.92A24.29,24.29,0,0,0,168,186v6a8,8,0,0,1-8,8H96a8,8,0,0,1-8-8v-6a24.11,24.11,0,0,0-9.3-19A79.87,79.87,0,0,1,48,104.45C47.76,61.09,82.72,25,126.07,24A80,80,0,0,1,208,104Z" opacity="0.2"></path><path d="M176,232a8,8,0,0,1-8,8H88a8,8,0,0,1,0-16h80A8,8,0,0,1,176,232Zm40-128a87.55,87.55,0,0,1-33.64,69.21A16.24,16.24,0,0,0,176,186v6a16,16,0,0,1-16,16H96a16,16,0,0,1-16-16v-6a16,16,0,0,0-6.23-12.66A87.59,87.59,0,0,1,40,104.49C39.74,56.83,78.26,17.14,125.88,16A88,88,0,0,1,216,104Zm-16,0a72,72,0,0,0-73.74-72c-39,.92-70.47,33.39-70.26,72.39a71.65,71.65,0,0,0,27.64,56.3A32,32,0,0,1,96,186v6h64v-6a32.15,32.15,0,0,1,12.47-25.35A71.65,71.65,0,0,0,200,104Zm-16.11-9.34a57.6,57.6,0,0,0-46.56-46.55,8,8,0,0,0-2.66,15.78c16.57,2.79,30.63,16.85,33.44,33.45A8,8,0,0,0,176,104a9,9,0,0,0,1.35-.11A8,8,0,0,0,183.89,94.66Z"></path></svg></span> Perché queste scelte</summary><ul><li><strong>Una soluzione pronta invece del modello costruito a mano.</strong> Il centro del corso sono gli agenti, non il designer delle tabelle. Importare la soluzione richiede pochi minuti e garantisce che nomi logici e valori delle scelte siano esattamente quelli citati da prompt, skill e flow dei laboratori: non resta nessun errore di battitura da scoprire quando un agente fallisce una scrittura.</li><li><strong>Dataverse invece di una lista SharePoint o di un Excel.</strong> Il processo ha relazioni (una proposta ha un proponente, un programma, una o più valutazioni), regole sui tipi di dato e codici univoci. Dataverse le gestisce in modo nativo, rispetta la sicurezza per ruolo e agenti, prompt e flow lo leggono e scrivono con il connettore Dataverse.</li><li><strong>Codici con numerazione automatica.</strong> Persone e agenti si scambiano codici leggibili (PP-1003), non GUID. Il codice lo genera Dataverse, così l&#39;agente non ha mai motivo di inventarlo: rilegge quello assegnato al salvataggio.</li><li><strong>Criteri come righe di una tabella.</strong> Pesi e descrizioni sono dati che il PMO può cambiare senza toccare gli agenti. Il grounding legge sempre la versione aggiornata.</li><li><strong>Nomi logici decisi esplicitamente.</strong> Prompt, skill e flow citano i nomi logici delle colonne (<code>csm_requestedbudget</code>, <code>csm_proposalstatus</code>...) e i valori numerici delle scelte. Nella soluzione sono fissati una volta per tutte: le istruzioni dei laboratori si possono copiare così come sono.</li><li><strong>Scelte locali e lookup veri.</strong> Canale, stato e raccomandazione sono scelte proprie della colonna, con i valori numerici del publisher (770000000, 770000001...); i collegamenti tra tabelle sono lookup, non testi con un codice, così un agente non può collegare una proposta a un programma che non esiste.</li><li><strong>Budget come numero intero.</strong> Evita le colonne di tipo valuta (tasso di cambio, valuta della transazione) ed è sufficiente per confronti e regole.</li><li><strong>Programma vuoto finché non è confermato.</strong> Quando una proposta potrebbe rientrare in due programmi decide una persona: un lookup vuoto rende visibile lo stato &quot;da confermare&quot;.</li><li><strong>Il documento in una colonna File.</strong> Il business case resta sul record della proposta: il flow carica il PDF nella colonna <strong>Business Case Document</strong> e lo riscarica quando il prompt deve leggerlo.</li><li><strong>Proposal Status come scelta personalizzata.</strong> Lo stato di sistema (Active, Inactive) resta disponibile per archiviare; lo stato del processo ha valori propri.</li></ul></details><h2 id="che-cosa-contiene-la-soluzione" tabindex="-1">Che cosa contiene la soluzione <a class="header-anchor" href="#che-cosa-contiene-la-soluzione" aria-label="Permalink to &quot;Che cosa contiene la soluzione&quot;">​</a></h2><p>Non c&#39;è niente da costruire, ma prima di scrivere il primo agente conviene leggere il modello: ogni prompt, flow e skill dei laboratori successivi cita queste tabelle, questi nomi logici e questi valori. Dopo l&#39;importazione si possono ritrovare nel proprio ambiente: aprire la soluzione, selezionare una tabella e poi <strong>Columns</strong>; la colonna <strong>Logical name</strong> (o <strong>Name</strong>) mostra il nome logico.</p><table tabindex="0"><thead><tr><th>Componente</th><th>Nome</th><th>Contenuto</th></tr></thead><tbody><tr><td>Tabelle</td><td>5 tabelle con prefisso <code>csm_</code></td><td>Program, Evaluation Criterion, Requester, Proposal, Assessment, con moduli e viste</td></tr><tr><td>App model-driven</td><td><strong>PMO Demand Hub</strong> (<code>csm_PMODemandHub</code>)</td><td>Navigazione in tre gruppi, home page e Proposal Board</td></tr><tr><td>Risorse web</td><td><code>csm_/pmo/...</code></td><td>Home page e Proposal Board (HTML, CSS, JavaScript), anime.js 4.2.2, icone delle tabelle, logo e icona dell&#39;app, tema personalizzato</td></tr><tr><td>Publisher</td><td><strong>CSM Solutions</strong> (<code>CSMSolutions</code>)</td><td>Prefisso <code>csm</code>, prefisso delle scelte <code>77000</code></td></tr></tbody></table><h3 id="tabelle-e-relazioni" tabindex="-1">Tabelle e relazioni <a class="header-anchor" href="#tabelle-e-relazioni" aria-label="Permalink to &quot;Tabelle e relazioni&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tabella</th><th>Nome logico</th><th>Colonna primaria</th><th>Collegata a (lookup)</th></tr></thead><tbody><tr><td>Program</td><td><code>csm_program</code></td><td>Name (<code>csm_name</code>)</td><td>-</td></tr><tr><td>Evaluation Criterion</td><td><code>csm_criterion</code></td><td>Name (<code>csm_name</code>)</td><td>Program</td></tr><tr><td>Requester</td><td><code>csm_requester</code></td><td>Name (<code>csm_name</code>)</td><td>-</td></tr><tr><td>Proposal</td><td><code>csm_proposal</code></td><td>Title (<code>csm_title</code>)</td><td>Requester, Program</td></tr><tr><td>Assessment</td><td><code>csm_assessment</code></td><td>Title (<code>csm_title</code>)</td><td>Proposal, Program</td></tr></tbody></table><p>Tutte le relazioni sono lookup molti a uno. Eliminare un programma o una proposta non elimina le righe collegate: il lookup su criteri, proposte o valutazioni rimane vuoto. Le tabelle hanno un proprietario (colonna <strong>Owner</strong>), quindi la sicurezza per ruolo di Dataverse vale anche per gli agenti.</p><h3 id="program" tabindex="-1">Program <a class="header-anchor" href="#program" aria-label="Permalink to &quot;Program&quot;">​</a></h3><p>Il programma di investimento è il punto di partenza di ogni valutazione: decide quali criteri si applicano e quale budget è disponibile. Criteri, proposte e valutazioni lo citano con un lookup. Il codice PG-### è inserito dal PMO (arriva dal piano degli investimenti), per questo è un testo obbligatorio e non un numero automatico.</p><table tabindex="0"><thead><tr><th>Colonna</th><th>Nome logico</th><th>Tipo e regole</th></tr></thead><tbody><tr><td>Name</td><td><code>csm_name</code></td><td>Testo, obbligatorio</td></tr><tr><td>Program Code</td><td><code>csm_programcode</code></td><td>Testo, obbligatorio, massimo 10 caratteri</td></tr><tr><td>Description</td><td><code>csm_description</code></td><td>Testo su più righe</td></tr><tr><td>Available Budget (EUR)</td><td><code>csm_availablebudget</code></td><td>Numero intero, minimo 0</td></tr></tbody></table><h3 id="evaluation-criterion" tabindex="-1">Evaluation Criterion <a class="header-anchor" href="#evaluation-criterion" aria-label="Permalink to &quot;Evaluation Criterion&quot;">​</a></h3><p>I criteri sono il cuore della valutazione e cambiano più spesso degli agenti: il PMO può modificare un peso o una descrizione senza toccare istruzioni, prompt o skill. Tenerli come righe collegate al programma permette agli agenti di leggere sempre la versione in vigore.</p><table tabindex="0"><thead><tr><th>Colonna</th><th>Nome logico</th><th>Tipo e regole</th></tr></thead><tbody><tr><td>Name</td><td><code>csm_name</code></td><td>Testo, obbligatorio</td></tr><tr><td>Description</td><td><code>csm_description</code></td><td>Testo su più righe</td></tr><tr><td>Weight</td><td><code>csm_weight</code></td><td>Numero intero da 0 a 100; i pesi di un programma sommano a 100</td></tr><tr><td>Program</td><td><code>csm_program</code></td><td>Lookup a <strong>Program</strong></td></tr></tbody></table><h3 id="requester" tabindex="-1">Requester <a class="header-anchor" href="#requester" aria-label="Permalink to &quot;Requester&quot;">​</a></h3><p>Lo stesso dipendente può presentare più proposte nel corso dell&#39;anno. Una tabella separata, con l&#39;email come chiave di deduplica, evita di ricopiare nome, ruolo e funzione in ogni proposta e permette di vedere lo storico di chi propone.</p><table tabindex="0"><thead><tr><th>Colonna</th><th>Nome logico</th><th>Tipo e regole</th></tr></thead><tbody><tr><td>Name</td><td><code>csm_name</code></td><td>Testo, obbligatorio</td></tr><tr><td>Requester Code</td><td><code>csm_requestercode</code></td><td>Numerazione automatica <code>RQ-{SEQNUM:4}</code></td></tr><tr><td>Email</td><td><code>csm_email</code></td><td>Testo in formato email</td></tr><tr><td>Role</td><td><code>csm_role</code></td><td>Testo</td></tr><tr><td>Department</td><td><code>csm_department</code></td><td>Testo</td></tr></tbody></table><h3 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h3><p>La proposta è la tabella su cui lavorano tutti: intake, valutazione, dossier. Contiene i dati estratti dal business case, i dati sul canale di arrivo (chat o email) e lo stato del processo. Due scelte meritano attenzione: lo <strong>Proposal Status</strong> è una colonna propria, distinta dallo stato di sistema, e il documento si conserva sul record nella colonna File <strong>Business Case Document</strong>.</p><table tabindex="0"><thead><tr><th>Colonna</th><th>Nome logico</th><th>Tipo e regole</th></tr></thead><tbody><tr><td>Title</td><td><code>csm_title</code></td><td>Testo, obbligatorio</td></tr><tr><td>Proposal Code</td><td><code>csm_proposalcode</code></td><td>Numerazione automatica <code>PP-{SEQNUM:4}</code></td></tr><tr><td>Summary</td><td><code>csm_summary</code></td><td>Testo su più righe, massimo 4000 caratteri</td></tr><tr><td>Cover Message</td><td><code>csm_message</code></td><td>Testo su più righe, massimo 4000 caratteri</td></tr><tr><td>Source Email</td><td><code>csm_sourceemail</code></td><td>Testo in formato email</td></tr><tr><td>Requested Budget (EUR)</td><td><code>csm_requestedbudget</code></td><td>Numero intero, minimo 0</td></tr><tr><td>Duration (Months)</td><td><code>csm_durationmonths</code></td><td>Numero intero da 0 a 120</td></tr><tr><td>Channel</td><td><code>csm_channel</code></td><td>Scelta: Chat, Email</td></tr><tr><td>Proposal Status</td><td><code>csm_proposalstatus</code></td><td>Scelta: Received, Assessed, Review Scheduled</td></tr><tr><td>Submission Date</td><td><code>csm_submissiondate</code></td><td>Solo data</td></tr><tr><td>Requester</td><td><code>csm_requester</code></td><td>Lookup a <strong>Requester</strong></td></tr><tr><td>Program</td><td><code>csm_program</code></td><td>Lookup a <strong>Program</strong>, vuoto finché il programma non è confermato</td></tr><tr><td>Business Case Document</td><td><code>csm_businesscasedocument</code></td><td>File, fino a 32 MB</td></tr></tbody></table><h3 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h3><p>La valutazione è separata dalla proposta perché è un atto preciso, con data, programma di riferimento, punteggio e motivazione: se il Comitato chiede una rivalutazione, la storia resta leggibile. Il <strong>Criteria Detail</strong> conserva la tabella riga per riga, così il dossier può riportare i livelli registrati senza rivalutare la proposta.</p><table tabindex="0"><thead><tr><th>Colonna</th><th>Nome logico</th><th>Tipo e regole</th></tr></thead><tbody><tr><td>Title</td><td><code>csm_title</code></td><td>Testo, obbligatorio</td></tr><tr><td>Assessment Code</td><td><code>csm_assessmentcode</code></td><td>Numerazione automatica <code>AS-{SEQNUM:4}</code></td></tr><tr><td>Proposal</td><td><code>csm_proposal</code></td><td>Lookup a <strong>Proposal</strong></td></tr><tr><td>Program</td><td><code>csm_program</code></td><td>Lookup a <strong>Program</strong></td></tr><tr><td>Score</td><td><code>csm_score</code></td><td>Numero decimale da 0 a 100, un decimale</td></tr><tr><td>Criteria Detail</td><td><code>csm_criteriadetail</code></td><td>Testo su più righe, massimo 10000 caratteri</td></tr><tr><td>Rationale</td><td><code>csm_rationale</code></td><td>Testo su più righe, massimo 4000 caratteri</td></tr><tr><td>Recommendation</td><td><code>csm_recommendation</code></td><td>Scelta: Recommended, Needs Further Review, Not Recommended</td></tr><tr><td>Assessment Date</td><td><code>csm_assessmentdate</code></td><td>Solo data</td></tr><tr><td>Review Dossier</td><td><code>csm_reviewdossier</code></td><td>File, fino a 32 MB, per conservare il dossier sul record (nel Lab S06 il dossier viene salvato in OneDrive)</td></tr></tbody></table><h3 id="codici-automatici-e-scelte" tabindex="-1">Codici automatici e scelte <a class="header-anchor" href="#codici-automatici-e-scelte" aria-label="Permalink to &quot;Codici automatici e scelte&quot;">​</a></h3><p>Le colonne <strong>Requester Code</strong>, <strong>Proposal Code</strong> e <strong>Assessment Code</strong> sono a numerazione automatica: Dataverse assegna il valore al salvataggio, partendo dal seed predefinito 1000. In un ambiente nuovo il primo proponente è quindi RQ-1000, la prima proposta PP-1000, la prima valutazione AS-1000.</p><p>Le tre colonne di scelta sono locali (appartengono alla colonna, non sono scelte globali condivise con altre tabelle) e usano il prefisso <code>77000</code> del publisher. Gli agenti scrivono questi valori numerici:</p><table tabindex="0"><thead><tr><th>Colonna</th><th>Opzioni e valori</th></tr></thead><tbody><tr><td>Channel (<code>csm_channel</code>)</td><td>Chat (770000000), Email (770000001)</td></tr><tr><td>Proposal Status (<code>csm_proposalstatus</code>)</td><td>Received (770000000), Assessed (770000001), Review Scheduled (770000002)</td></tr><tr><td>Recommendation (<code>csm_recommendation</code>)</td><td>Recommended (770000000), Needs Further Review (770000001), Not Recommended (770000002)</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M200,88l-72,72H96V128l72-72Z" opacity="0.2"></path><path d="M229.66,58.34l-32-32a8,8,0,0,0-11.32,0l-96,96A8,8,0,0,0,88,128v32a8,8,0,0,0,8,8h32a8,8,0,0,0,5.66-2.34l96-96A8,8,0,0,0,229.66,58.34ZM124.69,152H104V131.31l64-64L188.69,88ZM200,76.69,179.31,56,192,43.31,212.69,64ZM224,128v80a16,16,0,0,1-16,16H48a16,16,0,0,1-16-16V48A16,16,0,0,1,48,32h80a8,8,0,0,1,0,16H48V208H208V128a8,8,0,0,1,16,0Z"></path></svg></span>Nota</p><p><strong>Nessun valore predefinito</strong></p><p>Le colonne di scelta non hanno un valore predefinito. Lo stato <strong>Received</strong> di una nuova proposta lo scrivono i flow di intake (Lab S02 e S05); il Proposal Board mostra nella colonna Received anche le proposte create a mano senza stato.</p></div><h3 id="moduli-e-viste" tabindex="-1">Moduli e viste <a class="header-anchor" href="#moduli-e-viste" aria-label="Permalink to &quot;Moduli e viste&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Elemento</th><th>Che cosa offre</th></tr></thead><tbody><tr><td>Modulo principale <strong>Information</strong></td><td>Scheda <strong>General</strong> su due colonne (dettagli a sinistra, testi lunghi e file a destra), codici automatici e scelte nell&#39;intestazione, una scheda per ogni tabella collegata</td></tr><tr><td>Sottogriglie modificabili</td><td>Su un programma: <strong>Evaluation Criteria</strong>, <strong>Proposals</strong>, <strong>Assessments</strong>; su un proponente: <strong>Proposals</strong>; su una proposta: <strong>Assessments</strong>. Pesi, stati e altri valori si cambiano direttamente nella griglia</td></tr><tr><td>Creazione rapida</td><td>Un modulo di creazione rapida per ogni tabella, aperto da <strong>New</strong> nella home page o da <strong>+ New</strong> in un lookup o in una sottogriglia</td></tr><tr><td>Altri moduli</td><td>Modulo a scheda (elenchi sugli schermi piccoli) e modulo di visualizzazione rapida per ogni tabella</td></tr><tr><td>Viste</td><td>Active e Inactive per ogni tabella, più <strong>Proposals to Assess</strong>, <strong>Assessed Proposals</strong>, <strong>Proposals with Review Scheduled</strong>, <strong>Recommended Assessments</strong> e <strong>Assessments Needing Further Review</strong></td></tr></tbody></table><p>Le colonne File (<strong>Business Case Document</strong> e <strong>Review Dossier</strong>) compaiono anche nelle viste principali: nel modulo si seleziona la colonna per caricare un file e il nome del file per scaricarlo.</p><h3 id="l-app-model-driven" tabindex="-1">L&#39;app model-driven <a class="header-anchor" href="#l-app-model-driven" aria-label="Permalink to &quot;L&#39;app model-driven&quot;">​</a></h3><p>L&#39;app <strong>PMO Demand Hub</strong> contiene le cinque tabelle e due pagine web, organizzate in tre gruppi di navigazione:</p><table tabindex="0"><thead><tr><th>Gruppo</th><th>Voci</th></tr></thead><tbody><tr><td>Overview</td><td>Home (pagina web <code>csm_/pmo/home.html</code>)</td></tr><tr><td>Demand</td><td>Proposal Board (pagina web <code>csm_/pmo/board.html</code>), Proposals, Assessments, Requesters</td></tr><tr><td>Portfolio</td><td>Programs, Evaluation Criteria</td></tr></tbody></table><p>Ogni tabella ha un&#39;icona Phosphor duotone e un colore: Program blu, Evaluation Criterion viola, Requester verde acqua, Proposal ambra, Assessment verde. Le animazioni usano anime.js, incluso nella soluzione (<code>csm_/pmo/anime.min.js</code>), quindi le pagine non dipendono da una CDN esterna; per chi ha attivato la riduzione del movimento nel sistema operativo le animazioni vengono saltate.</p><h2 id="come-funziona-l-app-pmo-demand-hub" tabindex="-1">Come funziona l&#39;app PMO Demand Hub <a class="header-anchor" href="#come-funziona-l-app-pmo-demand-hub" aria-label="Permalink to &quot;Come funziona l&#39;app PMO Demand Hub&quot;">​</a></h2><p>Gli agenti scrivono, ma sono le persone del PMO a controllare: per ogni prova dei laboratori si aprirà l&#39;app per verificare i record. L&#39;app è anche lo strumento con cui gli analisti correggono a mano ciò che un agente non deve modificare, per esempio il programma di una proposta o lo stato del processo.</p><h3 id="home-page" tabindex="-1">Home page <a class="header-anchor" href="#home-page" aria-label="Permalink to &quot;Home page&quot;">​</a></h3><p>La home page si apre per prima e inizia con <strong>Manage data</strong>: una scheda per tabella con il numero di righe attive e quattro azioni.</p><table tabindex="0"><thead><tr><th>Azione</th><th>Che cosa fa</th></tr></thead><tbody><tr><td>View</td><td>Apre la vista della tabella</td></tr><tr><td>New</td><td>Apre il modulo di creazione rapida</td></tr><tr><td>Import</td><td>Apre il pannello di importazione per quella tabella</td></tr><tr><td>CSV</td><td>Scarica un modello CSV con i nomi di colonna corretti; per Programs ed Evaluation Criteria il modello contiene già i dati dei laboratori</td></tr></tbody></table><p>Accanto ci sono <strong>Load starter data</strong>, che crea o aggiorna in un solo passo i 5 programmi e i 25 criteri dei laboratori, e <strong>Import CSV</strong>. Sotto, la sezione <strong>Portfolio at a glance</strong> legge i dati dal vivo con la Web API di Dataverse: numeri chiave, barre del budget per programma (richiesto rispetto a disponibile, arancione quando un programma è oltre il budget), il grafico delle raccomandazioni, le ultime proposte con il loro stato e le quattro fasi del processo. Selezionando un programma o una proposta si apre il record.</p><p>Le immagini di questa sezione mostrano le pagine con i dati di esempio (etichetta <strong>Preview data</strong>), cioè come appaiono aperte fuori dall&#39;app, dove nulla viene scritto in Dataverse.</p><p><img src="'+r+'" alt=""></p><h3 id="pannello-import-csv" tabindex="-1">Pannello Import CSV <a class="header-anchor" href="#pannello-import-csv" aria-label="Permalink to &quot;Pannello Import CSV&quot;">​</a></h3><p>Il pannello funziona in quattro passi: scegliere la tabella, trascinare il file, controllare l&#39;anteprima e selezionare <strong>Import rows</strong>. Si occupa dei dettagli che di solito fanno fallire un&#39;importazione:</p><ul><li><strong>Separatori e formati.</strong> Virgola, punto e virgola (Excel in italiano salva con il punto e virgola) o tabulazione. Numeri come <code>180000</code>, <code>180.000</code> o <code>180,000</code>, decimali con il punto o con la virgola. Date come <code>YYYY-MM-DD</code> o <code>DD/MM/YYYY</code>.</li><li><strong>Nomi di colonna.</strong> Nomi visualizzati in inglese, nomi logici e le intestazioni italiane dei file originali dei laboratori (ad esempio <em>Codice programma</em>, <em>Budget disponibile (EUR)</em>, <em>Peso</em>, <em>Programma</em>).</li><li><strong>Lookup.</strong> Programma per Program Code o Name, proponente per Email, Requester Code o Name, proposta per Proposal Code o Title.</li><li><strong>Scelte.</strong> Per etichetta (<em>Email</em>, <em>Review Scheduled</em>, <em>Needs Further Review</em>) o per valore (<em>770000001</em>).</li><li><strong>Creare o aggiornare.</strong> Con <strong>Update existing rows</strong> selezionato, le righe che corrispondono alla chiave vengono aggiornate invece che duplicate. Chiavi: Program Code per i programmi, Name e Program per i criteri, Email per i proponenti, Title per proposte e valutazioni.</li><li><strong>Errori chiari.</strong> Le righe con problemi vengono saltate ed elencate con numero di riga e motivo, ad esempio <em>Program &quot;PG-999&quot; not found in Programs</em>. Le altre righe vengono importate.</li></ul><p>Le tabelle padre vanno importate per prime: Programs, poi Evaluation Criteria e Requesters, poi Proposals, infine Assessments. Il pannello usa i permessi dell&#39;utente connesso: si può importare solo nelle tabelle in cui si ha il permesso di creare e scrivere righe.</p><p><img src="'+n+'" alt=""></p><h3 id="proposal-board" tabindex="-1">Proposal Board <a class="header-anchor" href="#proposal-board" aria-label="Permalink to &quot;Proposal Board&quot;">​</a></h3><p><strong>Proposal Board</strong>, prima voce del gruppo <strong>Demand</strong>, mostra le proposte attive come schede in tre colonne: Received, Assessed, Review Scheduled. Ogni colonna riporta il numero di proposte e il loro budget richiesto totale.</p><ul><li><strong>Cambiare stato</strong> trascinando una scheda in un&#39;altra colonna, oppure con il menu dello stato in fondo alla scheda (funziona anche da tastiera). La modifica viene salvata subito nella colonna <strong>Proposal Status</strong> e il messaggio di conferma ha il pulsante <strong>Undo</strong>. Se il salvataggio non riesce (ad esempio perché l&#39;utente non può modificare le proposte), la scheda torna nella sua colonna e viene mostrato il motivo.</li><li><strong>Leggere una proposta a colpo d&#39;occhio</strong>: codice, budget richiesto (in rosso quando supera il budget disponibile del programma), codice del programma oppure <em>Program to be confirmed</em>, punteggio dell&#39;ultima valutazione colorato secondo la raccomandazione, proponente.</li><li><strong>Trovare le proposte</strong> con la casella di ricerca (titolo, codice, proponente) e il filtro per programma, che prevede anche <em>Program to be confirmed</em>.</li><li><strong>Aprire il record</strong> selezionando il titolo; <strong>New proposal</strong> apre il modulo di creazione rapida.</li></ul><p>Le viste delle tabelle restano il posto per il lavoro in blocco: filtri, esportazione in Excel, importazione e modifica in griglia.</p><p><img src="'+l+'" alt=""></p><h2 id="prerequisiti" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisiti" aria-label="Permalink to &quot;Prerequisiti&quot;">​</a></h2><p>Per svolgere questo lab occorre avere a disposizione:</p><ul><li>Un ambiente di laboratorio con Dataverse (lo stesso dei fondamenti va bene) e il ruolo <strong>System Customizer</strong> o <strong>System Administrator</strong>.</li><li>La soluzione <a href="../../../resources/advanced/solution/PMODemandIT_1_0_0_0.zip" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>PMODemandIT_1_0_0_0.zip</code></span></a> (non gestita, versione 1.0.0.0). Contiene anche il publisher <strong>CSM Solutions</strong> (<code>CSMSolutions</code>) con prefisso <code>csm</code> e prefisso delle scelte <code>77000</code>: se esiste già dal Lab 01 dei fondamenti, l&#39;importazione lo aggiorna.</li><li>I file <a href="../../../resources/advanced/data/programs.csv" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>programs.csv</code></span></a> e <a href="../../../resources/advanced/data/evaluation-criteria.csv" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>evaluation-criteria.csv</code></span></a>, se si vogliono caricare i dati da CSV invece che con <strong>Load starter data</strong>.</li><li>Un sito SharePoint dove poter creare cartelle e caricare file (per la cartella della conoscenza PMO), e i file <a href="../../../resources/advanced/conoscenza/Zava_PMO_Linee_Guida_Business_Case.docx" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>Zava_PMO_Linee_Guida_Business_Case.docx</code></span></a> e <a href="../../../resources/advanced/conoscenza/Zava_Piano_Strategico_IT_2026-2028.pdf" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>Zava_Piano_Strategico_IT_2026-2028.pdf</code></span></a>.</li></ul><p>Per i laboratori successivi servono anche:</p><ul><li>le licenze per i connettori Office 365 Outlook, Office 365 Users, Microsoft Teams e OneDrive for Business nel tenant di laboratorio;</li><li>i <a href="https://github.com/cvn-computergross/copilot-studio-masterclass/tree/main/docs/resources/advanced/" target="_blank">materiali del caso pratico</a> (business case, email di prova, template del dossier, skill): ogni lab indica nei prerequisiti i file che usa.</li></ul><h2 id="importare-la-soluzione" tabindex="-1">Importare la soluzione <a class="header-anchor" href="#importare-la-soluzione" aria-label="Permalink to &quot;Importare la soluzione&quot;">​</a></h2><p>Una soluzione è il contenitore che il PMO sposterà da un ambiente all&#39;altro: sviluppo, collaudo, produzione. Se tabelle, app e agenti nascono fuori dalla soluzione, al momento del rilascio vanno cercati e aggiunti uno per uno, con il rischio di dimenticarne qualcuno. La soluzione <strong>PMO Demand IT</strong> è <strong>non gestita</strong>: dopo l&#39;importazione si può modificare, e impostarla come soluzione preferita fa sì che i componenti creati da qui in poi fuori dal contesto di una soluzione ci finiscano per impostazione predefinita.</p><div class="tip custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-knowledge"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M208,104a79.86,79.86,0,0,1-30.59,62.92A24.29,24.29,0,0,0,168,186v6a8,8,0,0,1-8,8H96a8,8,0,0,1-8-8v-6a24.11,24.11,0,0,0-9.3-19A79.87,79.87,0,0,1,48,104.45C47.76,61.09,82.72,25,126.07,24A80,80,0,0,1,208,104Z" opacity="0.2"></path><path d="M176,232a8,8,0,0,1-8,8H88a8,8,0,0,1,0-16h80A8,8,0,0,1,176,232Zm40-128a87.55,87.55,0,0,1-33.64,69.21A16.24,16.24,0,0,0,176,186v6a16,16,0,0,1-16,16H96a16,16,0,0,1-16-16v-6a16,16,0,0,0-6.23-12.66A87.59,87.59,0,0,1,40,104.49C39.74,56.83,78.26,17.14,125.88,16A88,88,0,0,1,216,104Zm-16,0a72,72,0,0,0-73.74-72c-39,.92-70.47,33.39-70.26,72.39a71.65,71.65,0,0,0,27.64,56.3A32,32,0,0,1,96,186v6h64v-6a32.15,32.15,0,0,1,12.47-25.35A71.65,71.65,0,0,0,200,104Zm-16.11-9.34a57.6,57.6,0,0,0-46.56-46.55,8,8,0,0,0-2.66,15.78c16.57,2.79,30.63,16.85,33.44,33.45A8,8,0,0,0,176,104a9,9,0,0,0,1.35-.11A8,8,0,0,0,183.89,94.66Z"></path></svg></span>Suggerimento</p><p><strong>Dove lavorare</strong></p><p>Lavorare in <a href="https://make.powerapps.com/" target="_blank" rel="noreferrer">Power Apps</a> per importare la soluzione e aprire l&#39;app. Prima di iniziare controllare in alto a destra che l&#39;ambiente sia quello di laboratorio.</p></div><h3 id="importare-il-file-della-soluzione" tabindex="-1">Importare il file della soluzione <a class="header-anchor" href="#importare-il-file-della-soluzione" aria-label="Permalink to &quot;Importare il file della soluzione&quot;">​</a></h3><ol><li>In <a href="https://make.powerapps.com/" target="_blank" rel="noreferrer">Power Apps</a> verificare l&#39;ambiente, selezionare <strong>Solutions</strong> e poi <strong>Import solution</strong>.</li><li>Selezionare <strong>Browse</strong>, scegliere il file <a href="../../../resources/advanced/solution/PMODemandIT_1_0_0_0.zip" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>PMODemandIT_1_0_0_0.zip</code></span></a> scaricato e selezionare <strong>Next</strong>.</li><li>Controllare i dettagli (soluzione <strong>PMO Demand IT</strong>, publisher <strong>CSM Solutions</strong>, versione 1.0.0.0) e selezionare <strong>Import</strong>. L&#39;importazione richiede qualche minuto: attendere il messaggio di conferma.</li><li>Aprire la soluzione <strong>PMO Demand IT</strong> e selezionare <strong>Publish all customizations</strong>.</li><li>Tornare all&#39;elenco delle soluzioni, selezionare <strong>PMO Demand IT</strong> e poi <strong>Set preferred solution</strong> nella barra dei comandi (oppure nel menu <strong>...</strong> accanto al nome), e confermare. Da ora i nuovi componenti finiscono per impostazione predefinita in questa soluzione; quando un lab chiede di scegliere la soluzione, ad esempio in <strong>Advanced settings</strong> alla creazione di un agente, selezionare comunque <strong>PMO Demand IT</strong>.</li><li>Verificare che <strong>PMO Demand IT</strong> sia indicata come soluzione preferita nell&#39;elenco delle soluzioni e che, aperta, contenga le cinque tabelle e l&#39;app <strong>PMO Demand Hub</strong>.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M200,88l-72,72H96V128l72-72Z" opacity="0.2"></path><path d="M229.66,58.34l-32-32a8,8,0,0,0-11.32,0l-96,96A8,8,0,0,0,88,128v32a8,8,0,0,0,8,8h32a8,8,0,0,0,5.66-2.34l96-96A8,8,0,0,0,229.66,58.34ZM124.69,152H104V131.31l64-64L188.69,88ZM200,76.69,179.31,56,192,43.31,212.69,64ZM224,128v80a16,16,0,0,1-16,16H48a16,16,0,0,1-16-16V48A16,16,0,0,1,48,32h80a8,8,0,0,1,0,16H48V208H208V128a8,8,0,0,1,16,0Z"></path></svg></span>Nota</p><p><strong>Componenti già presenti</strong></p><p>Se l&#39;ambiente contiene già il publisher CSM Solutions, la soluzione PMO Demand IT o una tabella <code>csm_program</code> con la sola colonna Name (ad esempio da un tentativo precedente fatto a mano), l&#39;importazione li aggiorna e aggiunge le colonne mancanti: non serve eliminarli prima. Se invece segnala un conflitto su una colonna esistente con un tipo diverso, eliminare quella colonna o quella tabella e importare di nuovo.</p></div><h2 id="caricare-i-dati-di-partenza" tabindex="-1">Caricare i dati di partenza <a class="header-anchor" href="#caricare-i-dati-di-partenza" aria-label="Permalink to &quot;Caricare i dati di partenza&quot;">​</a></h2><p>All&#39;inizio servono solo programmi e criteri: sono le regole con cui gli agenti valuteranno le proposte. Proponenti, proposte e valutazioni partono vuoti, perché li creano gli agenti durante i laboratori.</p><h3 id="aprire-l-app" tabindex="-1">Aprire l&#39;app <a class="header-anchor" href="#aprire-l-app" aria-label="Permalink to &quot;Aprire l&#39;app&quot;">​</a></h3><ol><li>Nella soluzione <strong>PMO Demand IT</strong> selezionare l&#39;app <strong>PMO Demand Hub</strong> e poi <strong>Play</strong> (oppure aprirla da <strong>Apps</strong> in Power Apps).</li><li>Copiare l&#39;indirizzo dell&#39;app dalla barra del browser, fino al parametro <code>appid</code> incluso (ad esempio <code>https://&lt;org&gt;.crm4.dynamics.com/main.aspx?appid=&lt;id&gt;</code>), e annotarlo: servirà nel Lab S05 per i link nelle card di Teams.</li><li>Scorrere la home page e aprire <strong>Proposal Board</strong> dal gruppo <strong>Demand</strong>. Per ora tabelle e colonne sono vuote: i dati arrivano con il passo successivo.</li></ol><h3 id="caricare-programmi-e-criteri" tabindex="-1">Caricare programmi e criteri <a class="header-anchor" href="#caricare-programmi-e-criteri" aria-label="Permalink to &quot;Caricare programmi e criteri&quot;">​</a></h3><ol><li>Tornare a <strong>Home</strong> nel gruppo <strong>Overview</strong> e selezionare <strong>Load starter data</strong>.</li><li>Attendere la fine dell&#39;operazione: le schede di <strong>Manage data</strong> mostrano 5 righe in <strong>Programs</strong> e 25 in <strong>Evaluation Criteria</strong>. Se programmi e criteri esistono già, vengono aggiornati e non duplicati.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M200,88l-72,72H96V128l72-72Z" opacity="0.2"></path><path d="M229.66,58.34l-32-32a8,8,0,0,0-11.32,0l-96,96A8,8,0,0,0,88,128v32a8,8,0,0,0,8,8h32a8,8,0,0,0,5.66-2.34l96-96A8,8,0,0,0,229.66,58.34ZM124.69,152H104V131.31l64-64L188.69,88ZM200,76.69,179.31,56,192,43.31,212.69,64ZM224,128v80a16,16,0,0,1-16,16H48a16,16,0,0,1-16-16V48A16,16,0,0,1,48,32h80a8,8,0,0,1,0,16H48V208H208V128a8,8,0,0,1,16,0Z"></path></svg></span>Nota</p><p><strong>Caricare i dati da CSV</strong></p><p>In alternativa si possono usare i file CSV:</p><ul><li><strong>Pannello Import CSV.</strong> Nella home page selezionare <strong>Import CSV</strong>, scegliere <strong>Programs</strong> e trascinare <a href="../../../resources/advanced/data/programs.csv" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>programs.csv</code></span></a>, poi scegliere <strong>Evaluation Criteria</strong> e trascinare <a href="../../../resources/advanced/data/evaluation-criteria.csv" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>evaluation-criteria.csv</code></span></a>.</li><li><strong>Importazione standard di Power Apps.</strong> Nella soluzione aprire la tabella <strong>Program</strong>, selezionare <strong>Import</strong> e poi <strong>Import data from Excel</strong> (accetta anche i CSV) e caricare <code>programs.csv</code>; ripetere con la tabella <strong>Evaluation Criterion</strong> e <code>evaluation-criteria.csv</code>. Il CSV usa i nomi visualizzati delle colonne come intestazioni, per questo la mappatura si risolve quasi da sola; la colonna <strong>Program</strong> va associata al lookup Program, che si risolve per nome del programma (i cinque nomi sono tutti diversi).</li></ul></div><h3 id="verificare-i-dati" tabindex="-1">Verificare i dati <a class="header-anchor" href="#verificare-i-dati" aria-label="Permalink to &quot;Verificare i dati&quot;">​</a></h3><ol><li>Aprire <strong>Programs</strong> dal gruppo <strong>Portfolio</strong> e controllare i cinque programmi:</li></ol><table tabindex="0"><thead><tr><th>Codice</th><th>Programma</th><th>Budget disponibile (EUR)</th></tr></thead><tbody><tr><td>PG-100</td><td>Digital Process Transformation</td><td>600000</td></tr><tr><td>PG-200</td><td>Security and Compliance</td><td>450000</td></tr><tr><td>PG-300</td><td>Data and Artificial Intelligence</td><td>500000</td></tr><tr><td>PG-400</td><td>Modern Workplace</td><td>300000</td></tr><tr><td>PG-500</td><td>Infrastructure and Cloud</td><td>800000</td></tr></tbody></table><ol start="2"><li>Aprire un programma e selezionare la scheda <strong>Evaluation Criteria</strong>: mostra i suoi 5 criteri in una griglia modificabile e la somma dei pesi è 100.</li><li>Controllare che <strong>Requesters</strong>, <strong>Proposals</strong> e <strong>Assessments</strong> siano vuoti.</li><li>Verificare la numerazione automatica: in <strong>Proposals</strong> selezionare <strong>New</strong>, inserire un <strong>Title</strong> di prova e selezionare <strong>Save</strong>. Dopo il salvataggio il <strong>Proposal Code</strong> compare nell&#39;intestazione del modulo e nella vista <strong>Active Proposals</strong>, nel formato <code>PP-####</code> (in un ambiente nuovo <code>PP-1000</code>).</li><li>Eliminare la proposta di prova (<strong>Delete</strong> nella barra dei comandi, poi confermare), così <strong>Proposals</strong> torna vuota. Il codice usato non viene riassegnato: la prima proposta registrata dagli agenti avrà il numero successivo.</li></ol><h2 id="passaggi-facoltativi" tabindex="-1">Passaggi facoltativi <a class="header-anchor" href="#passaggi-facoltativi" aria-label="Permalink to &quot;Passaggi facoltativi&quot;">​</a></h2><h3 id="rendere-modificabili-le-viste-principali" tabindex="-1">Rendere modificabili le viste principali <a class="header-anchor" href="#rendere-modificabili-le-viste-principali" aria-label="Permalink to &quot;Rendere modificabili le viste principali&quot;">​</a></h3><p>Le sottogriglie dei moduli sono già modificabili. Per modificare direttamente anche gli elenchi principali (per esempio cambiare il peso di molti criteri dalla vista Evaluation Criteria) occorre attivare la griglia modificabile sulla tabella, dall&#39;esplora soluzioni classico.</p><ol><li>Aprire la soluzione <strong>PMO Demand IT</strong> e, nella barra dei comandi, selezionare <strong>...</strong> e poi <strong>Switch to classic</strong>.</li><li>Espandere <strong>Entities</strong>, aprire la tabella (ad esempio <strong>Evaluation Criterion</strong>), selezionare la scheda <strong>Controls</strong> e poi <strong>Add Control</strong>.</li><li>Selezionare <strong>Editable Grid</strong> (oppure <strong>Power Apps grid control</strong>, la versione più recente, se l&#39;ambiente la propone) e poi <strong>Add</strong>. Nella nuova riga selezionare <strong>Web</strong> come client.</li><li>Selezionare <strong>Save</strong> e poi <strong>Publish</strong>. Ripetere per le altre tabelle che interessano, di solito Evaluation Criteria e Programs. Gli utenti possono comunque passare dalla griglia modificabile a quella in sola lettura mentre usano l&#39;app.</li></ol><h3 id="attivare-il-tema-personalizzato" tabindex="-1">Attivare il tema personalizzato <a class="header-anchor" href="#attivare-il-tema-personalizzato" aria-label="Permalink to &quot;Attivare il tema personalizzato&quot;">​</a></h3><p>La soluzione contiene un tema indaco con intestazione scura (<code>csm_/pmo/theme.xml</code>). Il tema si applica con il valore di ambiente dell&#39;impostazione <strong>Custom theme definition</strong>, che vale per tutte le app model-driven dell&#39;ambiente: per questo la soluzione non lo imposta e lo si attiva a mano, solo se si vuole.</p><ol><li>Nella soluzione <strong>PMO Demand IT</strong> selezionare <strong>Add existing</strong>, <strong>More</strong>, <strong>Setting</strong>.</li><li>Cercare <em>custom theme</em>, selezionare <strong>Custom theme definition</strong>, poi <strong>Next</strong> e <strong>Add</strong>.</li><li>Selezionare <strong>Custom theme definition</strong> nella soluzione e poi <strong>Edit</strong>. In <strong>Setting environment value</strong> selezionare <strong>New environment value</strong> e inserire <code>csm_/pmo/theme.xml</code>.</li><li>Selezionare <strong>Save</strong> e poi <strong>Publish all customizations</strong>.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-platform"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M215.46,216H40.54C27.92,216,20,202.79,26.13,192.09L113.59,40.22c6.3-11,22.52-11,28.82,0l87.46,151.87C236,202.79,228.08,216,215.46,216Z" opacity="0.2"></path><path d="M236.8,188.09,149.35,36.22h0a24.76,24.76,0,0,0-42.7,0L19.2,188.09a23.51,23.51,0,0,0,0,23.72A24.35,24.35,0,0,0,40.55,224h174.9a24.35,24.35,0,0,0,21.33-12.19A23.51,23.51,0,0,0,236.8,188.09ZM222.93,203.8a8.5,8.5,0,0,1-7.48,4.2H40.55a8.5,8.5,0,0,1-7.48-4.2,7.59,7.59,0,0,1,0-7.72L120.52,44.21a8.75,8.75,0,0,1,15,0l87.45,151.87A7.59,7.59,0,0,1,222.93,203.8ZM120,144V104a8,8,0,0,1,16,0v40a8,8,0,0,1-16,0Zm20,36a12,12,0,1,1-12-12A12,12,0,0,1,140,180Z"></path></svg></span>Attenzione</p><p><strong>Ambiente condiviso</strong></p><p>Il valore di ambiente applica il tema a tutte le app model-driven dell&#39;ambiente che usano il nuovo aspetto. In un ambiente condiviso chiedere prima agli altri maker, oppure saltare questo passaggio: icone, colori e home page funzionano anche senza.</p></div><h2 id="conoscenza-pmo-in-sharepoint" tabindex="-1">Conoscenza PMO in SharePoint <a class="header-anchor" href="#conoscenza-pmo-in-sharepoint" aria-label="Permalink to &quot;Conoscenza PMO in SharePoint&quot;">​</a></h2><h3 id="creare-la-cartella-sharepoint-della-conoscenza-pmo" tabindex="-1">Creare la cartella SharePoint della conoscenza PMO <a class="header-anchor" href="#creare-la-cartella-sharepoint-della-conoscenza-pmo" aria-label="Permalink to &quot;Creare la cartella SharePoint della conoscenza PMO&quot;">​</a></h3><p>Le linee guida e il piano strategico sono documenti che il PMO aggiorna. Se vengono caricati direttamente nell&#39;agente, l&#39;agente ne usa una copia statica: quando il PMO cambia una regola, l&#39;agente continua ad applicare quella vecchia finché qualcuno non ricarica il file a mano. Collegando invece una cartella SharePoint, l&#39;agente legge sempre la versione corrente e risponde solo agli utenti che hanno il permesso di leggere quei documenti. Per questo i documenti di conoscenza vivono in SharePoint, come nel lavoro reale del PMO.</p><ol><li>Aprire il sito SharePoint del laboratorio. Se non se ne ha uno, creare un sito del team chiamato <code>Zava PMO</code> (da <a href="https://www.office.com/launch/sharepoint" target="_blank" rel="noreferrer">SharePoint</a>, <strong>Create site</strong>, <strong>Team site</strong>).</li><li>Aprire la raccolta <strong>Documents</strong> e creare una cartella <code>PMO Knowledge</code>.</li><li>Caricare nella cartella <a href="../../../resources/advanced/conoscenza/Zava_PMO_Linee_Guida_Business_Case.docx" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>Zava_PMO_Linee_Guida_Business_Case.docx</code></span></a> e <a href="../../../resources/advanced/conoscenza/Zava_Piano_Strategico_IT_2026-2028.pdf" download="" class="download"><span class="icon download-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V208H40V48A16,16,0,0,1,56,32H200A16,16,0,0,1,216,48Z" opacity="0.2"></path><path d="M224,144v64a8,8,0,0,1-8,8H40a8,8,0,0,1-8-8V144a8,8,0,0,1,16,0v56H208V144a8,8,0,0,1,16,0Zm-101.66,5.66a8,8,0,0,0,11.32,0l40-40a8,8,0,0,0-11.32-11.32L136,124.69V32a8,8,0,0,0-16,0v92.69L93.66,98.34a8,8,0,0,0-11.32,11.32Z"></path></svg></span><span class="download-name"><code>Zava_Piano_Strategico_IT_2026-2028.pdf</code></span></a>.</li><li>Annotare l&#39;indirizzo diretto della cartella: verrà usato nel Lab S01 come fonte di conoscenza. Si ottiene aggiungendo all&#39;indirizzo del sito il percorso della raccolta e della cartella; l&#39;indirizzo che compare nella barra del browser quando si apre la cartella (<code>.../Forms/AllItems.aspx?id=...</code>) e i link di condivisione hanno un&#39;altra forma e non vanno usati. L&#39;indirizzo deve essere simile a:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;tenant&gt;.sharepoint.com/sites/ZavaPMO/Shared%20Documents/PMO%20Knowledge</span></span></code></pre></div><ol start="5"><li>Verificare che i partecipanti che proveranno l&#39;agente abbiano almeno il permesso di <strong>lettura</strong> sul sito o sulla cartella. Chi non ce l&#39;ha non riceverà risposte da questi documenti, ed è il comportamento corretto.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M200,88l-72,72H96V128l72-72Z" opacity="0.2"></path><path d="M229.66,58.34l-32-32a8,8,0,0,0-11.32,0l-96,96A8,8,0,0,0,88,128v32a8,8,0,0,0,8,8h32a8,8,0,0,0,5.66-2.34l96-96A8,8,0,0,0,229.66,58.34ZM124.69,152H104V131.31l64-64L188.69,88ZM200,76.69,179.31,56,192,43.31,212.69,64ZM224,128v80a16,16,0,0,1-16,16H48a16,16,0,0,1-16-16V48A16,16,0,0,1,48,32h80a8,8,0,0,1,0,16H48V208H208V128a8,8,0,0,1,16,0Z"></path></svg></span>Nota</p><p><strong>Un solo sito per la classe</strong></p><p>Se il docente prepara un solo sito per tutta la classe, basta una cartella condivisa in lettura. Gli utenti guest non ricevono risposte da SharePoint, e se il tenant usa <strong>Restricted SharePoint Search</strong> la fonte SharePoint è bloccata: in questi casi usare il caricamento diretto dei file descritto nel Lab S01.</p></div><div class="important custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-topics"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M224,128a96,96,0,1,1-96-96A96,96,0,0,1,224,128Z" opacity="0.2"></path><path d="M144,176a8,8,0,0,1-8,8,16,16,0,0,1-16-16V128a8,8,0,0,1,0-16,16,16,0,0,1,16,16v40A8,8,0,0,1,144,176Zm88-48A104,104,0,1,1,128,24,104.11,104.11,0,0,1,232,128Zm-16,0a88,88,0,1,0-88,88A88.1,88.1,0,0,0,216,128ZM124,96a12,12,0,1,0-12-12A12,12,0,0,0,124,96Z"></path></svg></span>Importante</p><p><strong>Lab Completato</strong></p><p>Il PMO Demand Hub è pronto: soluzione importata, programmi e criteri caricati e cartella della conoscenza PMO in SharePoint. In questo laboratorio si è visto:</p><ul><li>come è progettato un modello dati pensato per essere usato da agenti: codici leggibili, nomi logici espliciti, regole nei dati;</li><li>come importare una soluzione non gestita con tabelle, app model-driven e risorse web e impostarla come soluzione preferita;</li><li>come caricare i dati di partenza e importare CSV con lookup nell&#39;app PMO Demand Hub;</li><li>come preparare in SharePoint una cartella di conoscenza che l&#39;agente legge sempre aggiornata.</li></ul><p>Nel prossimo laboratorio si crea il primo agente: l&#39;Agente Demand IT, l&#39;orchestratore del sistema.</p></div>',102)])])}const b=o(s,[["render",d]]);export{v as __pageData,b as default};
